<template>
  <AppMultiComboboxQuery
    v-if="isMultiple"
    :items="selectItems"
    :value="value"
    :property-name="propertyName"
    :null-is-all="nullIsAll"
    :placeholder="placeholder"
    :input-placeholder="inputPlaceholder"
    :loading="isLoading"
    :error="error"
    :items-plural-name="itemsPluralName"
    :empty-text="emptyText"
    :icon="icon || FilterIcon"
    :is-first-page-only="isFirstPageOnly"
  />
  <AppComboboxQuery
    v-else
    :items="selectItems"
    :value="value ? value[0] : null"
    :property-name="propertyName"
    :null-is-all="nullIsAll"
    :placeholder="placeholder"
    :input-placeholder="inputPlaceholder"
    :loading="isLoading"
    :error="error"
    :items-plural-name="itemsPluralName"
    :empty-text="emptyText"
    :icon="icon || FilterIcon"
    :is-first-page-only="isFirstPageOnly"
  />
</template>
<script setup lang="ts">
import { getSelectorUserList, type GetSelectorUserListResponse, type UserRole, type UserStatus } from '~/client';
import { FilterIcon } from 'lucide-vue-next';

const props = withDefaults(
  defineProps<{
    value: string[] | null;
    propertyName: string;
    roles: UserRole[] | null;
    statuses: UserStatus[] | null;
    projectIds?: string[];

    placeholder: string;
    inputPlaceholder: string;
    emptyText: string;
    nullIsAll: boolean;
    itemsPluralName: string;
    icon?: any;
    isMultiple?: boolean;
    isFirstPageOnly?: boolean;
  }>(),
  {
    statuses: () => ['active'],
    projectIds: undefined,
    icon: undefined,
    isMultiple: true,
    isFirstPageOnly: true,
  }
);

const { data, isLoading, error } = useQuery({
  key: () => ['selector-users-list', props.roles, props.statuses, props.projectIds ?? null, String(props.isMultiple)],
  query: (): Promise<GetSelectorUserListResponse> =>
    getSelectorUserList({
      composable: '$fetch',
      query: ref({ roles: props.roles, statuses: props.statuses, project_ids: props.projectIds }),
    }),
});

const selectItems = computed(() => {
  return (
    data.value?.users.map((user) => ({
      name: `${user.first_name} ${user.last_name}`,
      value: user.id,
      subtitle: user.subcontractor_short_info?.name ?? null,
    })) || []
  );
});
</script>
